css:
.tfp-section {
  --ink: #2C5F68;
  --muted: #6B7280;
  --accent: #D97742;
  --paper: #F5F5F7;
  --line: #E5E7EB;

  font-family: system-ui, -apple-system, sans-serif;
  background-color: var(--paper);
  color: var(--ink);
  padding: 2rem;
  border-radius: 8px;
  max-width: 900px;
  margin: 0 auto;
}

.tfp-section header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 1rem;
}

.tfp-section h2 {
  font-size: 1.75rem;
  margin: 0 0 0.5rem 0;
  color: var(--ink);
}

.tfp-section .lead {
  font-size: 1.1rem;
  color: var(--muted);
  margin: 0;
}

.workspace {
  display: grid;
  gap: 2rem;
}

.formula-display {
  background: #fff;
  padding: 1.5rem;
  border-radius: 6px;
  border: 1px solid var(--line);
  text-align: center;
}

.formula-block {
  font-family: 'Courier New', monospace;
  font-size: 1.2rem;
  font-weight: bold;
}

.calc-row {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5rem;
  margin: 0.5rem 0;
  flex-wrap: wrap;
}

.var {
  color: var(--accent);
  min-width: 3ch;
  text-align: right;
  display: inline-block;
}

.op {
  color: var(--muted);
}

.result {
  color: var(--ink);
  border-bottom: 2px solid var(--ink);
  padding: 0 0.25rem;
}

.formula-desc {
  font-size: 0.85rem;
  color: var(--muted);
  font-family: system-ui, sans-serif;
  font-weight: normal;
  margin-top: 0.5rem;
}

.controls-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.5rem;
}

.control-card {
  background: #fff;
  padding: 1.25rem;
  border-radius: 6px;
  border: 1px solid var(--line);
}

.control-card label {
  display: block;
  font-weight: 600;
  margin-bottom: 0.75rem;
  font-size: 0.95rem;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.source-btn-wrap {
  flex-shrink: 0;
  margin-left: 0.5rem;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  font-size: 0.75rem;
  padding: 0.1rem 0.4rem;
  border-radius: 4px;
  cursor: pointer;
}

.source-btn:hover {
  background: var(--muted);
  color: #fff;
}

.slider-wrap {
  margin-bottom: 0.5rem;
}

input[type="range"] {
  width: 100%;
  accent-color: var(--accent);
  cursor: pointer;
}

.value-display {
  text-align: right;
  font-family: 'Courier New', monospace;
  font-weight: bold;
  color: var(--accent);
  font-size: 1.1rem;
}

.control-card .note {
  font-size: 0.85rem;
  color: var(--muted);
  margin: 0.5rem 0 0 0;
  line-height: 1.4;
}

.result-panel {
  background: var(--ink);
  color: #fff;
  padding: 2rem;
  border-radius: 6px;
  text-align: center;
}

.result-panel h3 {
  margin: 0 0 1rem 0;
  font-size: 1.1rem;
  font-weight: normal;
  opacity: 0.9;
}

.big-number {
  font-size: 3.5rem;
  font-weight: 700;
  line-height: 1;
  margin-bottom: 0.5rem;
  font-variant-numeric: tabular-nums;
}

.big-number .unit {
  font-size: 1.5rem;
  vertical-align: super;
  opacity: 0.8;
}

.interpretation {
  font-size: 1rem;
  opacity: 0.9;
  margin: 0 0 1rem 0;
}

.annual-estimate {
  font-size: 0.9rem;
  opacity: 0.7;
  margin-bottom: 1.5rem;
}

.reset-btn {
  background: rgba(255,255,255,0.2);
  border: 1px solid rgba(255,255,255,0.4);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.9rem;
}

.reset-btn:hover {
  background: rgba(255,255,255,0.3);
}

.evidence-context {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--line);
}

.evidence-context h4 {
  font-size: 1rem;
  margin: 0 0 0.75rem 0;
  color: var(--muted);
}

.evidence-context ul {
  margin: 0;
  padding-left: 1.25rem;
  font-size: 0.9rem;
  color: var(--ink);
}

.evidence-context li {
  margin-bottom: 0.5rem;
}

.inline-source {
  background: transparent;
  border: none;
  color: var(--accent);
  font-size: 0.8rem;
  cursor: pointer;
  padding: 0;
  text-decoration: underline;
}

@media (max-width: 600px) {
  .tfp-section {
    padding: 1rem;
  }
  .big-number {
    font-size: 2.5rem;
  }
  .calc-row {
    flex-direction: column;
    gap: 0.25rem;
  }
}

javascript:
(function() {
  const els = {
    exposure: document.getElementById('input-exposure'),
    automation: document.getElementById('input-automation'),
    savings: document.getElementById('input-savings'),
    dispExposure: document.getElementById('disp-exposure'),
    dispAutomation: document.getElementById('disp-automation'),
    dispSavings: document.getElementById('disp-savings'),
    valExposure: document.getElementById('val-exposure'),
    valAutomation: document.getElementById('val-automation'),
    valSavings: document.getElementById('val-savings'),
    valResult: document.getElementById('val-result'),
    bigResult: document.getElementById('big-result'),
    annualResult: document.getElementById('annual-result'),
    reset: document.getElementById('btn-reset')
  };

  const defaults = {
    exposure: 0.20,
    automation: 0.23,
    savings: 0.144
  };

  function formatPercent(val, decimals) {
    return (val * 100).toFixed(decimals);
  }

  function update() {
    const exp = parseFloat(els.exposure.value);
    const auto = parseFloat(els.automation.value);
    const sav = parseFloat(els.savings.value);

    const result = exp * auto * sav;
    const resultPercent = result * 100;
    const annual = resultPercent / 10;

    // Update displays
    els.dispExposure.textContent = formatPercent(exp, 0);
    els.dispAutomation.textContent = formatPercent(auto, 0);
    els.dispSavings.textContent = formatPercent(sav, 1);

    // Update formula visual
    els.valExposure.textContent = exp.toFixed(2);
    els.valAutomation.textContent = auto.toFixed(2);
    els.valSavings.textContent = sav.toFixed(3);
    els.valResult.textContent = result.toFixed(4);

    // Update main result
    els.bigResult.textContent = resultPercent.toFixed(2);
    els.annualResult.textContent = annual.toFixed(3);
  }

  function reset() {
    els.exposure.value = defaults.exposure;
    els.automation.value = defaults.automation;
    els.savings.value = defaults.savings;
    update();
  }

  els.exposure.addEventListener('input', update);
  els.automation.addEventListener('input', update);
  els.savings.addEventListener('input', update);
  els.reset.addEventListener('click', reset);

  // Initialize
  update();
})();
